example.snippet:
package main

import (
	"context"
	"time"
)

type MyModule struct{}

// Run a build with cache invalidation
func (m *MyModule) Build(
	ctx context.Context,
) (string, error) {
	output, err := dag.Container().
		From("alpine").
		// comment out the line below to see the cached date output
		WithEnvVariable("CACHEBUSTER", time.Now().String()).
		WithExec([]string{"date"}).
		Stdout(ctx)

	if err != nil {
		return "", err
	}

	return output, nil
}

from datetime import datetime
from dagger import dag, function, object_type
@object_type class MyModule: @function async def build(self) -> str: """Run a build with cache invalidation""" output = ( dag.container() .from_("alpine") # comment out the line below to see the cached date output .with_env_variable("CACHEBUSTER", str(datetime.now())) .with_exec(["date"]) .stdout() ) return await output

import { dag, object, func } from "@dagger.io/dagger"

@object()
class MyModule {
  /**
   * Run a build with cache invalidation
   */
  @func()
  async build(): Promise {
    const ref = await dag
      .container()
      .from("alpine")
      // comment out the line below to see the cached date output
      .withEnvVariable("CACHEBUSTER", Date.now().toString())
      .withExec(["date"])
      .stdout()

    return ref
  }
}
